.joy_breadcrumb {
  position: fixed;
  z-index: 50;
  top: 75px;
  width: 100%;
  height: 40px;
  overflow: hidden;
  margin: 0 -15px;
  background-color: #0E38DF;
}
.joy_breadcrumb.has-overflow::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 40px;
  background: linear-gradient(to right, #0E38DF 0%, #0E38DF 60%, transparent 100%);
  z-index: 1;
  pointer-events: none;
}
@media (min-width: 768px) {
  .joy_breadcrumb.has-overflow::before {
    width: 60px;
  }
}
.joy_breadcrumb.has-overflow.at-start::before {
  opacity: 0;
  transition: opacity 0.2s ease;
}
.joy_breadcrumb.has-overflow:not(.at-start)::before {
  opacity: 1;
  transition: opacity 0.2s ease;
}
.joy_breadcrumb.has-overflow:not(.at-end)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 40px;
  background: linear-gradient(to left, #0E38DF 0%, #0E38DF 60%, transparent 100%);
  z-index: 1;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.2s ease;
}
@media (min-width: 768px) {
  .joy_breadcrumb.has-overflow:not(.at-end)::after {
    width: 60px;
  }
}
.joy_breadcrumb.has-overflow.at-end::after {
  opacity: 0;
  transition: opacity 0.2s ease;
}
.joy_breadcrumb ol {
  margin: 0 auto;
  padding: 12px 0;
  background-color: #0E38DF;
  border: 0;
  border-radius: 0;
  color: #FFFFFF;
  display: flex;
  flex-direction: row;
  justify-content: flex-start;
  overflow-x: auto;
  overflow-y: hidden;
  flex-wrap: nowrap;
  scroll-behavior: smooth;
  position: relative;
  max-width: calc(100vw - 48px);
  text-transform: uppercase;
}
@media (min-width: 768px) {
  .joy_breadcrumb ol {
    padding: 12px 0;
    max-width: calc(100vw - 80px);
  }
}
.joy_breadcrumb ol::-webkit-scrollbar {
  display: none;
}
.joy_breadcrumb ol {
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.joy_breadcrumb ol::after {
  content: "";
  position: absolute;
  right: 0;
}
.joy_breadcrumb ol li {
  font-size: 16px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
}
.joy_breadcrumb ol li:before {
  color: #FFFFFF !important;
}
.joy_breadcrumb ol li a {
  color: #FFFFFF;
  font-size: 16px;
}
.joy_breadcrumb ol li.active {
  color: #FFFFFF;
  font-weight: 600;
}

