@keyframes fadeIn {
  from {
    opacity: 0;
    transform: rotate3d(-1, 0, 0, -45deg) translateY(-100%);
  }
  to {
    transform: rotate3d(1, 0, 0, 0deg) translateY(0);
    opacity: 1;
  }
}
@keyframes fadeOut {
  from {
    transform: rotate3d(1, 0, 0, 0deg) translateY(0);
    opacity: 1;
  }
  to {
    transform: rotate3d(1, 0, 0, -45deg) translateY(100%);
    opacity: 0;
  }
}

