  text-align: center;
  padding: 40px 20px;
  position: relative;
  display: block;
}
.promotion-entries-gallery-sec .promotion-entries-gallery-wrapper {
  position: relative;
  z-index: 5;
}
.promotion-entries-gallery-sec h2 {
  font-size: 24px;
  line-height: 28px;
  text-transform: none;
  margin: 0 auto 32px;
}
@media (min-width: 1200px) {
  .promotion-entries-gallery-sec h2 {
    font-size: 36px;
    line-height: 40px;
    margin: 0 auto 40px;
  }
}
.promotion-entries-gallery-sec .food {
  position: absolute;
  display: none;
}
@media (min-width: 992px) {
  .promotion-entries-gallery-sec .food {
    display: block;
  }
}
.promotion-entries-gallery-sec .food.left-food-svg-mobile {
  left: 0;
  top: 10%;
}
.promotion-entries-gallery-sec .food.right-food-svg-mobile {
  right: 0;
  bottom: 10%;
  transform: scaleX(-1);
}
.promotion-entries-gallery-sec .promotion-entries-gallery {
  --gallery-gap: 14px;
  max-width: 1142px;
  margin: 0 auto 20px;
  gap: var(--gallery-gap);
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--gallery-gap);
}
