.brand-like {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  background-color: white;
  border-radius: 100%;
  position: absolute;
  top: 30px;
  right: 26px;
  z-index: 1;
  cursor: pointer;
  box-shadow: -4px 4px 15px 0px rgba(0, 0, 0, 0.1019607843);
  padding-top: 2px;
}
.brand-like svg {
  transition: all 0.3s ease-in-out;
}
.brand-like.liked svg {
  animation: like-pulse 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) 1 both;
  will-change: transform;
}
.brand-like.liked svg path {
  fill: #E31722;
  stroke: transparent;
}

.brands-submenu--brand-item .brand-like, .js-brand-likes-slider-item .brand-like {
  top: 0;
  right: 0;
  border-radius: 0;
  border-bottom-left-radius: 20px;
}

@keyframes like-pulse {
  0% {
    transform: scale(1);
  }
  18% {
    transform: scale(1.32);
  } /* bigger pop */
  40% {
    transform: scale(0.86);
  } /* deeper dip */
  65% {
    transform: scale(1.18);
  } /* rebound */
  100% {
    transform: scale(1);
  }
}
